from __future__ import annotations

from typing import Any, Callable

DEFAULTS = {"port": 8080, "host": "0.0.0.0", "workers": 4, "debug": False}


def _valid_positive_int(value: Any) -> bool:
    return isinstance(value, int) and value >= 1


def _valid_port(value: Any) -> bool:
    return isinstance(value, int) and 1 <= value <= 65535


def _valid_host(value: Any) -> bool:
    return isinstance(value, str) and len(value) > 0


_VALIDATORS: dict[str, Callable[[Any], bool]] = {
    "port": _valid_port,
    "host": _valid_host,
    "workers": _valid_positive_int,
    "debug": lambda value: isinstance(value, bool),
}


def load_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        return dict(DEFAULTS)

    for key, default in DEFAULTS.items():
        if key not in raw:
            continue
        if not _VALIDATORS[key](raw[key]):
            return dict(DEFAULTS)

    config = dict(DEFAULTS)
    config.update({key: raw[key] for key in DEFAULTS if key in raw})
    return config

