    "port": lambda value: isinstance(value, int) and 1 <= value <= 65535,
    "host": lambda value: isinstance(value, str) and len(value) > 0,
    "workers": lambda value: isinstance(value, int) and value >= 1,
    "debug": lambda value: isinstance(value, bool),
}


def load_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        return dict(DEFAULTS)

    for key, value in raw.items():
        if key in _VALIDATORS and _VALIDATORS[key](value):
            continue
        return dict(DEFAULTS)

    return {**DEFAULTS, **{key: value for key, value in raw.items() if key in DEFAULTS}}

