    def flag(key: tuple) -> str:
        if key not in counts:
            return "empty"
        return "degraded" if key in degraded else "good"

    return [[flag((row, col)) for col in range(width)] for row in range(height)]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


