VALID_METHODS = frozenset(("card", "transfer"))

_REQUIRED_MEMBER = ("id", "status", "tier")
_REQUIRED_PAYMENT = ("amount", "method")


def _validate_fields(member: dict, payment: dict) -> Optional[str]:
    for field in _REQUIRED_MEMBER:
        if field not in member:
            return "missing member field"
    for field in _REQUIRED_PAYMENT:
        if field not in payment:
            return "missing payment field"
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return "bad member id"
    return None


def _extra_active(member: dict) -> Tuple[int, str]:
    return 0, "renewed"


def _extra_lapsed(member: dict) -> Tuple[int, str]:
    expired = member.get("expired_days")
    if not isinstance(expired, int) or expired < 0:
        return None, "bad expiry"
    if expired <= GRACE_DAYS:
        return LATE_FEE, "renewed"
    return REINSTATE_SURCHARGE, "reinstated"


def _extra_suspended(member: dict) -> Tuple[int, str]:
    strikes = member.get("strikes")
    if not isinstance(strikes, int) or strikes < 0:
        return None, "bad strikes"
    if strikes >= MAX_STRIKES:
        return None, "too many strikes"
    return TIER_FEES[member["tier"]] // 2, "reactivated"


_STATUS_RULES: dict[str, Callable[[dict], Tuple[int, str]]] = {
    "active": _extra_active,
    "lapsed": _extra_lapsed,
    "suspended": _extra_suspended,
}


def _finalize(payment: dict, member: dict, fee: int, action: str) -> dict:
    amount = payment.get("amount")
    if not isinstance(amount, int) or amount <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in VALID_METHODS:
        return {"ok": False, "error": "unsupported method"}
    if amount < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {
        "ok": True,
        "status": action,
        "fee": fee,
        "receipt": f"{payment['method']}:{member['id']}:{action}:{fee}",
    }


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment

    error = _validate_fields(member, payment)
    if error:
        return {"ok": False, "error": error}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}
    rule = _STATUS_RULES.get(status)
    if rule is None:
        return {"ok": False, "error": "unknown status"}
    if member["tier"] not in VALID_TIERS:
        return {"ok": False, "error": "unknown tier"}

    fee_extra, action = rule(member)
    if fee_extra is None:
        return {"ok": False, "error": action}

    fee = TIER_FEES[member["tier"]] + fee_extra
    return _finalize(payment, member, fee, action)

