MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

VALID_TIERS = frozenset(TIER_FEES)
VALID_METHODS = frozenset({"card", "transfer"})
Plan = Callable[[dict], Tuple[int, str]]


def _bad(error: str) -> dict:
    return {"ok": False, "error": error}


def _expiry_error(member: dict) -> Optional[str]:
    expired_days = member.get("expired_days")
    return None if isinstance(expired_days, int) and expired_days >= 0 else "bad expiry"


def _strikes_error(member: dict) -> Optional[str]:
    strikes = member.get("strikes")
    if not isinstance(strikes, int) or strikes < 0:
        return "bad strikes"
    return "too many strikes" if strikes >= MAX_STRIKES else None


def _plan_active(member: dict) -> Tuple[int, str]:
    return TIER_FEES[member["tier"]], "renewed"


def _plan_lapsed(member: dict) -> Tuple[int, str]:
    if member["expired_days"] <= GRACE_DAYS:
        return TIER_FEES[member["tier"]] + LATE_FEE, "renewed"
    return TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE, "reinstated"


def _plan_suspended(member: dict) -> Tuple[int, str]:
    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    return fee, "reactivated"


def _validate(member: dict, payment: dict, extra: Optional[Callable[[dict], Optional[str]]]) -> Optional[str]:
    if member["tier"] not in VALID_TIERS:
        return "unknown tier"
    if extra is not None:
        error = extra(member)
        if error is not None:
            return error
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in VALID_METHODS:
        return "unsupported method"
    return None


def _handle(member: dict, payment: dict, extra: Optional[Callable[[dict], Optional[str]]], plan: Plan) -> dict:
    error = _validate(member, payment, extra)
    if error is not None:
        return _bad(error)
    fee, status = plan(member)
    if payment["amount"] < fee:
        return _bad("insufficient payment")
    receipt = f"{payment['method']}:{member['id']}:{status}:{fee}"
    return {"ok": True, "status": status, "fee": fee, "receipt": receipt}


def _reject_banned(member: dict, payment: dict) -> dict:
    return _bad("member banned")


def _reject_unknown(member: dict, payment: dict) -> dict:
    return _bad("unknown status")


_HANDLERS: dict = {
    "banned": _reject_banned,
    "active": lambda m, p: _handle(m, p, None, _plan_active),
    "lapsed": lambda m, p: _handle(m, p, _expiry_error, _plan_lapsed),
    "suspended": lambda m, p: _handle(m, p, _strikes_error, _plan_suspended),
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return _bad("malformed input")
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return _bad("missing member field")
    if "amount" not in payment or "method" not in payment:
        return _bad("missing payment field")
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return _bad("bad member id")
    return _HANDLERS.get(member["status"], _reject_unknown)(member, payment)

