        "status": status,
        "fee": fee,
        "receipt": _receipt(method, member_id, status, fee),
    }


def _process_active(member: dict, payment: dict) -> dict:
    if not _valid_tier(member["tier"]):
        return _bad("unknown tier")
    if not _valid_amount(payment["amount"]):
        return _bad("bad amount")
    if not _valid_method(payment["method"]):
        return _bad("unsupported method")
    fee = TIER_FEES[member["tier"]]
    if payment["amount"] < fee:
        return _bad("insufficient payment")
    return _success(payment["method"], member["id"], "renewed", fee)


def _process_lapsed(member: dict, payment: dict) -> dict:
    if not _valid_tier(member["tier"]):
        return _bad("unknown tier")
    if not isinstance(member.get("expired_days"), int) or member["expired_days"] < 0:
        return _bad("bad expiry")
    if not _valid_amount(payment["amount"]):
        return _bad("bad amount")
    if not _valid_method(payment["method"]):
        return _bad("unsupported method")
    if member["expired_days"] <= GRACE_DAYS:
        fee = TIER_FEES[member["tier"]] + LATE_FEE
        status = "renewed"
    else:
        fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
        status = "reinstated"
    if payment["amount"] < fee:
        return _bad("insufficient payment")
    return _success(payment["method"], member["id"], status, fee)


def _process_suspended(member: dict, payment: dict) -> dict:
    if not _valid_tier(member["tier"]):
        return _bad("unknown tier")
    if not isinstance(member.get("strikes"), int) or member["strikes"] < 0:
        return _bad("bad strikes")
    if member["strikes"] >= MAX_STRIKES:
        return _bad("too many strikes")
