from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

_VALID_METHODS = frozenset({"card", "transfer"})


def _tier_fee(member: dict) -> int | None:
    tier = member["tier"]
    return None if tier not in TIER_FEES else TIER_FEES[tier]


def _amount_method_error(payment: dict) -> str | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in _VALID_METHODS:
        return "unsupported method"
    return None


def _finish(member: dict, payment: dict, fee: int, new_status: str) -> dict:
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {
        "ok": True,
        "status": new_status,
        "fee": fee,
        "receipt": f"{payment['method']}:{member['id']}:{new_status}:{fee}",
    }


def _handle_active(member: dict, payment: dict) -> dict:
    fee = _tier_fee(member)
    if fee is None:
        return {"ok": False, "error": "unknown tier"}
    error = _amount_method_error(payment)
    if error is not None:
        return {"ok": False, "error": error}
    return _finish(member, payment, fee, "renewed")


def _handle_lapsed(member: dict, payment: dict) -> dict:
    fee = _tier_fee(member)
    if fee is None:
        return {"ok": False, "error": "unknown tier"}
    if (
        "expired_days" not in member
        or not isinstance(member["expired_days"], int)
        or member["expired_days"] < 0
    ):
        return {"ok": False, "error": "bad expiry"}
    error = _amount_method_error(payment)
    if error is not None:
        return {"ok": False, "error": error}
    if member["expired_days"] <= GRACE_DAYS:
        return _finish(member, payment, fee + LATE_FEE, "renewed")
    return _finish(member, payment, fee + REINSTATE_SURCHARGE, "reinstated")


def _handle_suspended(member: dict, payment: dict) -> dict:
    fee = _tier_fee(member)
    if fee is None:
        return {"ok": False, "error": "unknown tier"}
    if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    error = _amount_method_error(payment)
    if error is not None:
        return {"ok": False, "error": error}
    return _finish(member, payment, fee + fee // 2, "reactivated")


_HANDLERS = {
    "active": _handle_active,
    "lapsed": _handle_lapsed,
    "suspended": _handle_suspended,
}


def _prepare(raw_member: object, raw_payment: object) -> tuple[dict, dict, str | None]:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {}, {}, "malformed input"
    if "id" not in raw_member or "status" not in raw_member or "tier" not in raw_member:
        return {}, {}, "missing member field"
    if "amount" not in raw_payment or "method" not in raw_payment:
        return {}, {}, "missing payment field"
    if not isinstance(raw_member["id"], str) or len(raw_member["id"]) == 0:
        return {}, {}, "bad member id"
    return raw_member, raw_payment, None


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    member, payment, error = _prepare(raw_member, raw_payment)
    if error is not None:
        return {"ok": False, "error": error}
    if member["status"] == "banned":
        return {"ok": False, "error": "member banned"}
    handler = _HANDLERS.get(member["status"])
    if handler is None:
        return {"ok": False, "error": "unknown status"}
    return handler(member, payment)

