from __future__ import annotations

_LENGTH_THRESHOLD = 8
_MIN_LENGTH = 4
_REPEAT_PENALTY_THRESHOLD = 3
_LONG_PASSWORD_THRESHOLD = 12


def _length_score(pw: str) -> int:
    if len(pw) >= _LENGTH_THRESHOLD:
        return 1
    if len(pw) < _MIN_LENGTH:
        return -1
    return 0


def _class_score(pw: str) -> int:
    has_lower = any(ch.islower() for ch in pw)
    has_upper = any(ch.isupper() for ch in pw)
    has_digit = any(ch.isdigit() for ch in pw)
    has_symbol = any(not ch.isalnum() for ch in pw)
    return int(has_lower) + int(has_upper) + int(has_digit) + int(has_symbol)


def _repeat_score(pw: str) -> int:
    repeats = sum(1 for i in range(1, len(pw)) if pw[i] == pw[i - 1])
    if repeats >= _REPEAT_PENALTY_THRESHOLD:
        return -2
    if repeats >= 1:
        return -1
    return 0


def _bonus_score(pw: str, has_symbol: bool) -> int:
    if len(pw) >= _LONG_PASSWORD_THRESHOLD and has_symbol:
        return 1
    return 0


def password_strength(pw: str) -> int:
    has_symbol = any(not ch.isalnum() for ch in pw)
    score = (
        _length_score(pw)
        + _class_score(pw)
        + _repeat_score(pw)
        + _bonus_score(pw, has_symbol)
    )
    return max(score, 0)

