    if payment_error := _payment_error(payment):
        return {"ok": False, "error": payment_error}
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {
        "ok": True,
        "status": new_status,
        "fee": fee,
        "receipt": _receipt(member, payment, new_status, fee),
    }


def _payment_error(payment: dict) -> str | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in _VALID_METHODS:
        return "unsupported method"
    return None


def _active(member: dict, payment: dict) -> dict:
    return _settle(member, payment, TIER_FEES[member["tier"]], "renewed")


def _lapsed(member: dict, payment: dict) -> dict:
    if "expired_days" not in member or not isinstance(
        member["expired_days"], int
    ) or member["expired_days"] < 0:
        return {"ok": False, "error": "bad expiry"}
    if member["expired_days"] <= GRACE_DAYS:
        return _settle(
            member, payment, TIER_FEES[member["tier"]] + LATE_FEE, "renewed"
        )
    return _settle(
        member,
        payment,
        TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE,
        "reinstated",
    )


def _suspended(member: dict, payment: dict) -> dict:
    if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    return _settle(
        member,
        payment,
        TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2,
        "reactivated",
    )


def _banned(member: dict, payment: dict) -> dict:
    return {"ok": False, "error": "member banned"}


_HANDLERS = {
    "active": _active,
    "lapsed": _lapsed,
    "suspended": _suspended,
    "banned": _banned,
}


def _member_error(member: dict) -> str | None:
    if "id" not in member or "status" not in member or "tier" not in member:
        return "missing member field"
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return "bad member id"
    return None


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    if member_error := _member_error(raw_member):
        return {"ok": False, "error": member_error}
    if "amount" not in raw_payment or "method" not in raw_payment:
        return {"ok": False, "error": "missing payment field"}

    handler = _HANDLERS.get(raw_member["status"])
    if handler is None:
        return {"ok": False, "error": "unknown status"}
    if raw_member["tier"] not in TIER_FEES:
        return {"ok": False, "error": "unknown tier"}

