def to_number(text: str) -> float | None:
    if not isinstance(text, str):
        return None

    match = _NUM_RE.match(text.strip())
    if match is None:
        return None

    sign, whole, frac = match.groups()
    literal = sign + whole
    if frac is not None:
        literal += "." + frac
    return float(literal)

