from __future__ import annotations

_WEEKEND_SUPPLEMENT = 4.0
_FRIDAY_SUPPLEMENT = 2.0

_YOUTH_MEMBER_DISCOUNT = 0.9
_ADULT_MEMBER_DISCOUNT = 0.8


def ticket_price(age: int, day: str, is_member: bool) -> float:
    price = _base_price(age)
    price += _day_supplement(day)
    price *= _member_discount(age, is_member)
    return price


def _base_price(age: int) -> float:
    if age < 3:
        return 0.0
    if age < 12:
        return 8.0
    if age < 18:
        return 12.0
    if age < 65:
        return 18.0
    return 10.0


def _day_supplement(day: str) -> float:
    if day in ("saturday", "sunday"):
        return _WEEKEND_SUPPLEMENT
    if day == "friday":
        return _FRIDAY_SUPPLEMENT
    return 0.0


def _member_discount(age: int, is_member: bool) -> float:
    if not is_member:
        return 1.0
    return _YOUTH_MEMBER_DISCOUNT if age < 18 else _ADULT_MEMBER_DISCOUNT

