type Validation = { parsed: Parsed } | { error: string };

const PREFERRED_LOYALTY_YEARS = 3;
const SEASONS = new Set(["low", "high"]);

const CONFIG: Record<string, CategoryConfig> = {
  standard: { baseRate: 80, highSurcharge: 30, maxNights: 14, maxGuests: 2 },
  suite: {
    baseRate: 150,
