  ["user.updated", ({ id }) => ({ status: "ok", message: `updated user ${String(id)}` })],
  ["user.deleted", ({ id }) => ({ status: "ok", message: `deleted user ${String(id)}` })],
  ["order.placed", ({ orderId }) => ({ status: "ok", message: `order placed ${String(orderId)}` })],
  ["order.cancelled", ({ orderId }) => ({ status: "ok", message: `order cancelled ${String(orderId)}` })],
  ["order.shipped", ({ orderId }) => ({ status: "ok", message: `order shipped ${String(orderId)}` })],
  ["payment.succeeded", ({ paymentId }) => ({ status: "ok", message: `payment succeeded ${String(paymentId)}` })],
  ["payment.failed", ({ paymentId }) => ({ status: "error", message: `payment failed ${String(paymentId)}` })],
  ["invoice.issued", ({ invoiceId }) => ({ status: "ok", message: `invoice issued ${String(invoiceId)}` })],
  ["invoice.voided", ({ invoiceId }) => ({ status: "ok", message: `invoice voided ${String(invoiceId)}` })],
]);

