export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  maxNights: number;
  maxGuests: number;
  baseRate: number;
  highRate: number;
  name: string;
  minNights?: number;
  extraPerGuest?: number;
  flatFee?: number;
}

interface ValidRequest {
  category: CategoryConfig;
  nights: number;
  guests: number;
  season: "low" | "high";
  loyaltyYears: number;
  vip: boolean;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: { name: "standard", maxNights: 14, maxGuests: 2, baseRate: 80, highRate: 30 },
  suite: { name: "suite", maxNights: 21, maxGuests: 4, baseRate: 150, highRate: 60, extraPerGuest: 25 },
  villa: { name: "villa", minNights: 3, maxNights: 28, maxGuests: 8, baseRate: 300, highRate: 120, flatFee: 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseShape(raw);
  if (!parsed.ok) {
    return { ok: false, error: parsed.error };
  }
  const category = CATEGORIES[parsed.category];
  if (!category) {
    return { ok: false, error: "unknown category" };
  }
  const nightError = nightProblem(category, parsed.nights);
  if (nightError) {
    return { ok: false, error: nightError };
  }
  const guestError = guestProblem(category, parsed.guests);
  if (guestError) {
    return { ok: false, error: guestError };
  }
  if (parsed.season !== "low" && parsed.season !== "high") {
    return { ok: false, error: "bad season" };
  }
  return buildQuote(category, parsed);
}

function parseShape(raw: unknown): { ok: true; request: Shape } | { ok: false; error: string } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  return {
    ok: true,
    request: {
      category: String(req.category),
      nights: req.nights as number,
      guests: req.guests as number,
      season: req.season as "low" | "high",
      loyaltyYears: req.loyaltyYears as number,
      vip: req.coupon === "VIP",
    },
  };
}

interface Shape {
  category: string;
  nights: number;
  guests: number;
  season: "low" | "high";
  loyaltyYears: number;
  vip: boolean;
}

function nightProblem(category: CategoryConfig, nights: number): string | null {
  if (!Number.isInteger(nights) || nights < 1 || nights > category.maxNights) {
    return "bad nights";
  }
  if (category.minNights !== undefined && nights < category.minNights) {
    return "villa minimum stay";
  }
  return null;
}

function guestProblem(category: CategoryConfig, guests: number): string | null {
  if (!Number.isInteger(guests) || guests < 1 || guests > category.maxGuests) {
    return "bad guests";
  }
  return null;
}

function buildQuote(category: CategoryConfig, req: Shape): QuoteResult {
  let total = category.baseRate * req.nights;
  if (req.season === "high") {
    total += category.highRate * req.nights;
  }
  const preferred = req.vip || req.loyaltyYears >= 3;
  if (preferred) {
    total -= Math.floor(total / 10);
  }
  if (category.extraPerGuest !== undefined && req.guests > 2) {
    total += category.extraPerGuest;
  }
  if (category.flatFee !== undefined) {
    total += category.flatFee;
  }
  const policy = preferred ? "flex" : "strict";
  const line = `${category.name}:${req.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

