  extraPerGuest?: number;
  flatFee?: number;
}

interface ValidRequest {
  category: CategoryConfig;
  nights: number;
  guests: number;
  season: "low" | "high";
  loyaltyYears: number;
  vip: boolean;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: { name: "standard", maxNights: 14, maxGuests: 2, baseRate: 80, highRate: 30 },
  suite: { name: "suite", maxNights: 21, maxGuests: 4, baseRate: 150, highRate: 60, extraPerGuest: 25 },
  villa: { name: "villa", minNights: 3, maxNights: 28, maxGuests: 8, baseRate: 300, highRate: 120, flatFee: 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  const validated = validateRequest(raw);
  if (!validated.ok) {
    return { ok: false, error: validated.error };
  }
  return buildQuote(validated.request);
}

function validateRequest(raw: unknown): { ok: true; request: ValidRequest } | { ok: false; error: string } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const category = CATEGORIES[String(req.category)];
  if (!category) {
    return { ok: false, error: "unknown category" };
  }

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;

  if (!Number.isInteger(nights) || nights < 1 || nights > category.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (category.minNights !== undefined && nights < category.minNights) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > category.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  return {
    ok: true,
    request: {
      category,
      nights,
      guests,
      season: req.season,
      loyaltyYears: req.loyaltyYears as number,
      vip: req.coupon === "VIP",
    },
  };
}

function buildQuote(req: ValidRequest): QuoteResult {
  let total = req.category.baseRate * req.nights;
  if (req.season === "high") {
    total += req.category.highRate * req.nights;
  }
  const preferred = req.vip || req.loyaltyYears >= 3;
  if (preferred) {
    total -= Math.floor(total / 10);
  }
  if (req.category.extraPerGuest !== undefined && req.guests > 2) {
    total += req.category.extraPerGuest;
  }
  if (req.category.flatFee !== undefined) {
    total += req.category.flatFee;
  }
  const policy = preferred ? "flex" : "strict";
  const line = `${req.category.name}:${req.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

