}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const FORMATS = ["json", "yaml", "text"] as const;
const LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

type FlagHandler = (args: string[], index: number, config: FlagConfig) => number;

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function takeValue(args: string[], index: number, flag: string): string {
  const value = args[++index];
  if (value === undefined) {
    throw new Error(`${flag} requires a path`);
  }
  return value;
}

function takeInteger(args: string[], index: number, flag: string): number {
  const value = Number(args[++index]);
  if (!Number.isInteger(value)) {
    throw new Error(`${flag} must be an integer`);
  }
  return value;
}

function takeEnum<T extends string>(
  args: string[],
  index: number,
  name: string,
  allowed: readonly T[],
): T {
  const value = args[++index];
  if (value === undefined || !(allowed as readonly string[]).includes(value)) {
    throw new Error(`unsupported ${name}: ${String(value)}`);
  }
  return value as T;
}

const FLAG_HANDLERS: Record<string, FlagHandler> = {
  "--verbose": (_, __, config) => {
    config.verbose = true;
    return 0;
  },
  "--quiet": (_, __, config) => {
    config.quiet = true;
    return 0;
  },
  "--dry-run": (_, __, config) => {
    config.dryRun = true;
    return 0;
  },
  "--force": (_, __, config) => {
    config.force = true;
    return 0;
  },
  "--no-color": (_, __, config) => {
    config.color = false;
    return 0;
  },
  "--strict": (_, __, config) => {
    config.strict = true;
    return 0;
  },
  "--output": (args, index, config) => {
    config.outputPath = takeValue(args, index, "--output");
    return 1;
  },
  "--config": (args, index, config) => {
    config.configPath = takeValue(args, index, "--config");
    return 1;
  },
  "--format": (args, index, config) => {
    config.format = takeEnum(args, index, "format", FORMATS);
    return 1;
  },
  "--log-level": (args, index, config) => {
    config.logLevel = takeEnum(args, index, "log level", LOG_LEVELS);
    return 1;
  },
  "--retries": (args, index, config) => {
    config.maxRetries = takeInteger(args, index, "--retries");
    return 1;
  },
  "--timeout": (args, index, config) => {
    config.timeoutMs = takeInteger(args, index, "--timeout");
    return 1;
  },
  "--parallel": (args, index, config) => {
    config.parallelism = takeInteger(args, index, "--parallel");
    return 1;
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const handler = FLAG_HANDLERS[arg];
    if (handler === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }
    i += handler(argv, i, config);
  }

  return config;
}

