export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const BOOLEAN_FLAGS: Record<string, { key: keyof FlagConfig; value: boolean }> = {
  "--verbose": {"key": "verbose", "value": true},
  "--quiet": {"key": "quiet", "value": true},
  "--dry-run": {"key": "dryRun", "value": true},
  "--force": {"key": "force", "value": true},
  "--no-color": {"key": "color", "value": false},
  "--strict": {"key": "strict", "value": true},
};

type ValueSetter = (raw: string, config: FlagConfig) => void;

const VALUE_FLAGS: Record<string, ValueSetter> = {
  "--output": (value, config) => {
    config.outputPath = value;
  },
  "--config": (value, config) => {
    config.configPath = value;
  },
  "--format": (value, config) => {
    if (!["json", "yaml", "text"].includes(value)) {
      throw new Error(`unsupported format: ${value}`);
    }
    config.format = value;
  },
  "--log-level": (value, config) => {
    if (!["debug", "info", "warn", "error"].includes(value)) {
      throw new Error(`unsupported log level: ${value}`);
    }
    config.logLevel = value;
  },
  "--retries": (value, config) => {
    config.maxRetries = parseInteger(value, "--retries");
  },
  "--timeout": (value, config) => {
    config.timeoutMs = parseInteger(value, "--timeout");
  },
  "--parallel": (value, config) => {
    config.parallelism = parseInteger(value, "--parallel");
  },
};

function parseInteger(value: string, flag: string): number {
  const num = Number(value);
  if (!Number.isInteger(num)) {
    throw new Error(`${flag} must be an integer`);
  }
  return num;
}

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function apply(name: string, inlineValue: string | undefined, config: FlagConfig): boolean {
  const key = inlineValue === undefined ? BOOLEAN_FLAGS[name] : undefined;
  if (key !== undefined) {
    (config as unknown as Record<string, boolean>)[key.key] = key.value;
    return true;
  }

  if (name in VALUE_FLAGS && inlineValue !== undefined) {
    VALUE_FLAGS[name]!(inlineValue, config);
    return true;
  }

  return false;
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const raw = argv[i]!;
    const flag = normalizeFlag(raw);

    let name = flag;
    let inlineValue: string | undefined;
    if (flag.startsWith("--") && flag.includes("=")) {
      const eq = flag.indexOf("=");
      name = flag.slice(0, eq);
      inlineValue = flag.slice(eq + 1);
    }

    if (apply(name, inlineValue, config)) {
      continue;
    }

    if (name in VALUE_FLAGS) {
      const value = argv[++i];
      if (value === undefined) {
        throw new Error(`${name} requires a value`);
      }
      VALUE_FLAGS[name]!(value, config);
      continue;
    }

    throw new Error(`unknown flag: ${flag}`);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

interface FlagSpec {
  optionalValue: boolean;
  apply: (config: FlagConfig, value: string | undefined) => void;
}

const FLAGS: Record<string, FlagSpec> = {
  "--verbose": { optionalValue: false, apply: (c) => (c.verbose = true) },
  "--quiet": { optionalValue: false, apply: (c) => (c.quiet = true) },
  "--dry-run": { optionalValue: false, apply: (c) => (c.dryRun = true) },
  "--force": { optionalValue: false, apply: (c) => (c.force = true) },
  "--no-color": { optionalValue: false, apply: (c) => (c.color = false) },
  "--strict": { optionalValue: false, apply: (c) => (c.strict = true) },

  "--output": {
    optionalValue: true,
    apply: (c, v) => {
      if (v === undefined || v === "") {
        throw new Error("--output requires a path");
      }
      c.outputPath = v;
    },
  },
  "--config": {
    optionalValue: true,
    apply: (c, v) => {
      if (v === undefined || v === "") {
        throw new Error("--config requires a path");
      }
      c.configPath = v;
    },
  },
  "--format": {
    optionalValue: true,
    apply: (c, v) => {
      requireChoice(v, ["json", "yaml", "text"], "--format");
      c.format = v!;
    },
  },
  "--log-level": {
    optionalValue: true,
    apply: (c, v) => {
      requireChoice(v, ["debug", "info", "warn", "error"], "--log-level");
      c.logLevel = v!;
    },
  },
  "--retries": {
    optionalValue: true,
    apply: (c, v) => (c.maxRetries = requireInteger(v, "--retries")),
  },
  "--timeout": {
    optionalValue: true,
    apply: (c, v) => (c.timeoutMs = requireInteger(v, "--timeout")),
  },
  "--parallel": {
    optionalValue: true,
    apply: (c, v) => (c.parallelism = requireInteger(v, "--parallel")),
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    i = applyFlag(config, argv, i);
  }

  return config;
}

function applyFlag(config: FlagConfig, argv: string[], i: number): number {
  const arg = normalizeFlag(argv[i]!);
  const spec = FLAGS[arg];
  if (!spec) {
    throw new Error(`unknown flag: ${arg}`);
  }

  let value: string | undefined;
  if (spec.optionalValue) {
    value = argv[i + 1];
    i++;
  }

  spec.apply(config, value);
  return i;
}

function requireInteger(value: string | undefined, flag: string): number {
  const num = Number(value);
  if (!Number.isInteger(num)) {
    throw new Error(`${flag} must be an integer`);
  }
  return num;
}

function requireChoice(
  value: string | undefined,
  allowed: string[],
  flag: string,
): void {
  if (value === undefined || !allowed.includes(value)) {
    throw new Error(`unsupported ${flag.replace(/^--/, "")}: ${String(value)}`);
  }
}

