export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const GRADE_THRESHOLDS: ReadonlyArray<readonly [number, string]> = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
];

export function gradeReport(record: StudentRecord): GradeReport {
  const { score, absences, extraCredit } = record;

  let letter = "F";
  for (const [threshold, grade] of GRADE_THRESHOLDS) {
    if (score >= threshold) {
      letter = grade;
      break;
    }
  }

  let modifier = "none";
  if (absences > 20) {
    letter = "F";
    modifier = "attendance-failure";
  } else if (extraCredit >= 5 && score >= 90) {
    modifier = "honors";
  }

  return { letter, modifier };
}

export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const LETTER_BY_MIN_SCORE: Array<[number, string]> = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
];

function letterForScore(score: number): string {
  for (const [minScore, letter] of LETTER_BY_MIN_SCORE) {
    if (score >= minScore) {
      return letter;
    }
  }
  return "F";
}

function modifierFor(record: StudentRecord): string {
  if (record.extraCredit >= 5 && record.score >= 90) {
    return "honors";
  }
  return "none";
}

export function gradeReport(record: StudentRecord): GradeReport {
  if (record.absences > 20) {
    return { letter: "F", modifier: "attendance-failure" };
  }

  return {
    letter: letterForScore(record.score),
    modifier: modifierFor(record),
  };
}

export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

export function gradeReport(record: StudentRecord): GradeReport {
  const letter = baseLetter(record.score);
  return applyModifier(letter, record);
}

function baseLetter(score: number): string {
  if (score >= 97) return "A+";
  if (score >= 93) return "A";
  if (score >= 90) return "A-";
  if (score >= 87) return "B+";
  if (score >= 83) return "B";
  if (score >= 73) return "C";
  if (score >= 60) return "D";
  return "F";
}

function applyModifier(
  letter: string,
  record: StudentRecord
): { letter: string; modifier: string } {
  if (record.absences > 20) {
    return { letter: "F", modifier: "attendance-failure" };
  }

  if (record.extraCredit >= 5 && record.score >= 90) {
    return { letter, modifier: "honors" };
  }

  return { letter, modifier: "none" };
}

export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const GRADE_BANDS: ReadonlyArray<[minScore: number, letter: string]> = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
  [Number.NEGATIVE_INFINITY, "F"],
];

export function gradeReport(record: StudentRecord): GradeReport {
  const { score, absences, extraCredit } = record;

  const band = GRADE_BANDS.find(([minScore]) => score >= minScore);
  let letter = band![1];

  let modifier: "none" | "attendance-failure" | "honors" = "none";

  if (absences > 20) {
    letter = "F";
    modifier = "attendance-failure";
  } else if (extraCredit >= 5 && score >= 90) {
    modifier = "honors";
  }

  return { letter, modifier };
}

export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const FAILURE_ABSENCE_THRESHOLD = 20;
const HONORS_EXTRA_CREDIT_THRESHOLD = 5;
const HONORS_SCORE_THRESHOLD = 90;

function scoreToLetter(score: number): string {
  if (score >= 97) return "A+";
  if (score >= 93) return "A";
  if (score >= 90) return "A-";
  if (score >= 87) return "B+";
  if (score >= 83) return "B";
  if (score >= 73) return "C";
  if (score >= 60) return "D";
  return "F";
}

export function gradeReport(record: StudentRecord): GradeReport {
  if (record.absences > FAILURE_ABSENCE_THRESHOLD) {
    return { letter: "F", modifier: "attendance-failure" };
  }

  const letter = scoreToLetter(record.score);

  const modifier =
    record.extraCredit >= HONORS_EXTRA_CREDIT_THRESHOLD &&
    record.score >= HONORS_SCORE_THRESHOLD
      ? "honors"
      : "none";

  return { letter, modifier };
