export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const LETTER_BY_SCORE: ReadonlyArray<readonly [number, string]> = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
];

function letterFor(score: number): string {
  for (const [threshold, letter] of LETTER_BY_SCORE) {
    if (score >= threshold) return letter;
  }
  return "F";
}

export function gradeReport(record: StudentRecord): GradeReport {
  if (record.absences > 20) {
    return { letter: "F", modifier: "attendance-failure" };
  }

  const modifier =
    record.extraCredit >= 5 && record.score >= 90 ? "honors" : "none";

  return { letter: letterFor(record.score), modifier };
}

