  for (const rule of EVENT_RULES[type]) {
    const value = event[rule.field];
    const valid = rule.optional && value === undefined ? true : rule.field === "qty" ? QTY_OK(value) : TEXT_OK(value);
    if (!valid) {
      const label = rule.field === "item" ? "item" : rule.field === "qty" ? "qty" : "id";
      return "event " + index + ": bad " + label;
    }
  }
  return null;
}

