  if (state.orders[event.id] !== undefined) {
    return "duplicate order";
  }
  const qty = event.qty as number;
  if (onHand(state.stock, event.item) >= qty) {
    state.stock[event.item] = onHand(state.stock, event.item) - qty;
    state.reserved[event.id] = { item: event.item, qty };
    state.orders[event.id] = "reserved";
  } else {
    state.queue.push(event.id);
