  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function isNonEmptyString(x: unknown): boolean {
  return typeof x === "string" && x.length > 0;
}

function isPositiveInt(x: unknown): boolean {
  return Number.isInteger(x) && (x as number) >= 1;
}

function isNonNegativeInt(x: unknown): boolean {
  return Number.isInteger(x) && (x as number) >= 0;
}

function level(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function serveQueue(state: State) {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHand = level(state.stock, want.item);
    if (onHand >= want.qty) {
      state.stock[want.item] = onHand - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseReservation(state: State, id: string, status: string) {
  const holding = state.reserved[id];
  state.stock[holding.item] = level(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  serveQueue(state);
}

function rejectUnrecognized(state: State) {
  state.rejected = state.rejected + 1;
}

type Handler = (state: State, event: Record<string, unknown>, index: number) => string | null;

function handleOrder(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = event.id;
  const item = event.item;
  const qty = event.qty;
  if (!isNonEmptyString(id)) return "event " + index + ": bad id";
  if (state.orders[id as string] !== undefined) return "event " + index + ": duplicate order";
  if (!isNonEmptyString(item)) return "event " + index + ": bad item";
  if (!isPositiveInt(qty)) return "event " + index + ": bad qty";
  if (level(state.stock, item as string) >= (qty as number)) {
    state.stock[item as string] = level(state.stock, item as string) - (qty as number);
    state.reserved[id as string] = { item: item as string, qty: qty as number };
    state.orders[id as string] = "reserved";
  } else {
    state.queue.push(id as string);
    state.pendingWants[id as string] = { item: item as string, qty: qty as number };
    state.orders[id as string] = "backordered";
  }
  return null;
}

function handleCancel(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = event.id;
  if (!isNonEmptyString(id)) return "event " + index + ": bad id";
  if (state.reserved[id as string] !== undefined) {
    releaseReservation(state, id as string, "cancelled");
  } else if (state.orders[id as string] === "backordered") {
    state.queue.splice(state.queue.indexOf(id as string), 1);
    delete state.pendingWants[id as string];
    state.orders[id as string] = "cancelled";
  } else {
    rejectUnrecognized(state);
  }
  return null;
}

function handleShip(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = event.id;
  const qty = event.qty;
  if (!isNonEmptyString(id)) return "event " + index + ": bad id";
  if (qty !== undefined && !isPositiveInt(qty)) return "event " + index + ": bad qty";
  const res = state.reserved[id as string];
  if (res === undefined) {
    rejectUnrecognized(state);
    return null;
  }
  const shipped = qty === undefined || (qty as number) === res.qty;
  if (shipped) {
    delete state.reserved[id as string];
    state.orders[id as string] = "shipped";
    return null;
  }
  if ((qty as number) < res.qty) {
    res.qty = res.qty - (qty as number);
    state.orders[id as string] = "partial";
    return null;
  }
  rejectUnrecognized(state);
  return null;
}

function handleRestock(state: State, event: Record<string, unknown>, index: number): string | null {
  const item = event.item;
  const qty = event.qty;
  if (!isNonEmptyString(item)) return "event " + index + ": bad item";
  if (!isPositiveInt(qty)) return "event " + index + ": bad qty";
  state.stock[item as string] = level(state.stock, item as string) + (qty as number);
  serveQueue(state);
  return null;
}

function handleExpire(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = event.id;
  if (!isNonEmptyString(id)) return "event " + index + ": bad id";
  if (state.reserved[id as string] !== undefined) {
    releaseReservation(state, id as string, "expired");
  } else {
    rejectUnrecognized(state);
  }
  return null;
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

function processOne(state: State, event: unknown, index: number): string | null {
  if (typeof event !== "object" || event === null) {
    return "event " + index + ": malformed";
  }
  const e = event as Record<string, unknown>;
  const handler = HANDLERS[e.type as string];
  if (handler === undefined) {
    return "event " + index + ": bad type";
  }
  return handler(state, e, index);
}

interface ParsedInput {
  ok: boolean;
  error?: string;
  stock?: unknown;
  events?: unknown[];
}

function parseInput(raw: unknown): ParsedInput {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  return { ok: true, stock: input.stock, events: input.events };
}

function parseStock(raw: unknown): { ok: boolean; error?: string; stock?: Record<string, number> } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "bad stock" };
  }
  const rawStock = raw as Record<string, unknown>;
  const stock: Record<string, number> = {};
  for (const item of Object.keys(rawStock)) {
    if (!isNonNegativeInt(rawStock[item])) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { ok: true, stock };
}

export function processEvents(raw: unknown): FulfillmentResult {
  const input = parseInput(raw);
  if (!input.ok) {
    return { ok: false, error: input.error };
  }
  const parsedStock = parseStock(input.stock);
  if (!parsedStock.ok || parsedStock.stock === undefined) {
    return { ok: false, error: parsedStock.error };
  }
  const state: State = {
    stock: parsedStock.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };
  const events = input.events as unknown[];
  for (let index = 0; index < events.length; index++) {
    const err = processOne(state, events[index], index);
    if (err !== null) {
      return { ok: false, error: err };
    }
  }
  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
