  stock[item] === undefined ? 0 : stock[item];
const isNonEmptyString = (v: unknown): v is string => typeof v === "string" && v.length > 0;
const isPositiveInt = (v: unknown): v is number => Number.isInteger(v) && (v as number) > 0;
const optionalQty = (v: unknown): boolean => v === undefined || isPositiveInt(v);

const id = (e: Event): string => e.id as string;
const item = (e: Event): string => e.item as string;
const qty = (e: Event): number => e.qty as number;

function fillBacklog(r: Registry): void {
  for (let position = 0; position < r.queue.length; position++) {
    const pendingId = r.queue[position];
    const want = r.pendingWants[pendingId];
    if (onHand(r.stock, want.item) < want.qty) {
      continue;
    }
    r.stock[want.item] = onHand(r.stock, want.item) - want.qty;
    r.reserved[pendingId] = { item: want.item, qty: want.qty };
    r.orders[pendingId] = "reserved";
    delete r.pendingWants[pendingId];
    r.queue.splice(position, 1);
    position = position - 1;
  }
}

function releaseAndFill(r: Registry, orderId: string, status: Status): void {
  const holding = r.reserved[orderId];
  r.stock[holding.item] = onHand(r.stock, holding.item) + holding.qty;
  delete r.reserved[orderId];
  r.orders[orderId] = status;
  fillBacklog(r);
}

function placeOrder(r: Registry, e: Event): void {
  if (onHand(r.stock, item(e)) >= qty(e)) {
    r.stock[item(e)] = onHand(r.stock, item(e)) - qty(e);
    r.reserved[id(e)] = { item: item(e), qty: qty(e) };
    r.orders[id(e)] = "reserved";
  } else {
    r.queue.push(id(e));
    r.pendingWants[id(e)] = { item: item(e), qty: qty(e) };
    r.orders[id(e)] = "backordered";
  }
}

function cancelOrder(r: Registry, e: Event): void {
  if (r.reserved[id(e)] !== undefined) {
    releaseAndFill(r, id(e), "cancelled");
  } else if (r.orders[id(e)] === "backordered") {
    r.queue.splice(r.queue.indexOf(id(e)), 1);
    delete r.pendingWants[id(e)];
    r.orders[id(e)] = "cancelled";
  } else {
    r.rejected++;
  }
}

function shipOrder(r: Registry, e: Event): void {
  const reserved = r.reserved[id(e)];
  if (reserved === undefined) {
    r.rejected++;
  } else if (e.qty === undefined || qty(e) === reserved.qty) {
    delete r.reserved[id(e)];
    r.orders[id(e)] = "shipped";
  } else if (qty(e) < reserved.qty) {
    reserved.qty = reserved.qty - qty(e);
    r.orders[id(e)] = "partial";
  } else {
    r.rejected++;
  }
}

function restock(r: Registry, e: Event): void {
  r.stock[item(e)] = onHand(r.stock, item(e)) + qty(e);
  fillBacklog(r);
}

function expireOrder(r: Registry, e: Event): void {
  if (r.reserved[id(e)] !== undefined) {
    releaseAndFill(r, id(e), "expired");
  } else {
    r.rejected++;
  }
}

type Action = (r: Registry, e: Event) => void;
type Check = [keyof Event, (v: unknown) => boolean];

const EVENT_CHECKS: Record<string, Check[]> = {
  [ORDER]: [
    ["id", isNonEmptyString],
    ["item", isNonEmptyString],
    ["qty", isPositiveInt],
  ],
  [CANCEL]: [["id", isNonEmptyString]],
  [SHIP]: [
    ["id", isNonEmptyString],
    ["qty", optionalQty],
  ],
  [RESTOCK]: [
    ["item", isNonEmptyString],
    ["qty", isPositiveInt],
  ],
  [EXPIRE]: [["id", isNonEmptyString]],
};

const ACTIONS: Record<string, Action> = {
  [ORDER]: placeOrder,
  [CANCEL]: cancelOrder,
  [SHIP]: shipOrder,
  [RESTOCK]: restock,
  [EXPIRE]: expireOrder,
};

function runOne(r: Registry, e: Event, type: string): void {
  for (const [key, test] of EVENT_CHECKS[type]) {
    if (!test(e[key])) {
      throw new Error("bad field");
    }
