export interface OrderItem {
  sku: string;
  quantity: number;
  unitPrice: number;
}

export interface Address {
  line1: string;
  city: string;
  postalCode: string;
  country: string;
}

export interface Order {
  id: string;
  customerId: string;
  items: OrderItem[];
  shippingAddress: Address | null;
  billingAddress: Address | null;
  totalCents: number;
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

function pushErrorIf(errors: string[], invalid: boolean, message: string): void {
  if (invalid) {
    errors.push(message);
  }
}

function validateItems(items: OrderItem[], errors: string[]): void {
  if (items.length === 0) {
    errors.push("order must contain at least one item");
    return;
  }
  for (const item of items) {
    pushErrorIf(errors, item.quantity <= 0, `item ${item.sku} has a non-positive quantity`);
  }
}

function isUnsupportedCurrency(currency: string): boolean {
  return currency !== "USD" && currency !== "EUR";
}

export function validateOrder(order: Order): ValidationResult {
  const errors: string[] = [];

  pushErrorIf(errors, order.id.length === 0, "order id is required");
  pushErrorIf(errors, order.customerId.length === 0, "customer id is required");

  validateItems(order.items, errors);

  if (order.shippingAddress === null) {
    errors.push("shipping address is required");
  } else {
    pushErrorIf(errors, order.shippingAddress.postalCode.trim().length === 0, "shipping postal code is required");
  }

  pushErrorIf(errors, order.billingAddress === null, "billing address is required");
  pushErrorIf(errors, order.totalCents <= 0, "order total must be positive");
  pushErrorIf(errors, isUnsupportedCurrency(order.currency), `unsupported currency: ${order.currency}`);

  return { valid: errors.length === 0, errors };
}

export interface OrderItem {
  sku: string;
  quantity: number;
  unitPrice: number;
}

export interface Address {
  line1: string;
  city: string;
  postalCode: string;
  country: string;
}

export interface Order {
  id: string;
  customerId: string;
  items: OrderItem[];
  shippingAddress: Address | null;
  billingAddress: Address | null;
  totalCents: number;
  currency: string;
}

