  const errors: string[] = [];

  const { items, shippingAddress, billingAddress } = order;

  requireField(order.id.length > 0, "order id is required", errors);
  requireField(order.customerId.length > 0, "customer id is required", errors);

  if (items.length === 0) {
    errors.push("order must contain at least one item");
