files.process_events.ts:
interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface Ctx {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

type Handler = (event: Record<string, unknown>, ctx: Ctx) => string | null;

function stockOf(ctx: Ctx, item: string): number {
  return ctx.stock[item] === undefined ? 0 : ctx.stock[item];
}

function tryFillBacklog(ctx: Ctx): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = stockOf(ctx, want.item);
    if (onHand < want.qty) {
      continue;
    }
    ctx.stock[want.item] = onHand - want.qty;
    ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
    ctx.orders[pendingId] = "reserved";
    delete ctx.pendingWants[pendingId];
    ctx.queue.splice(position, 1);
    position = position - 1;
  }
}

function releaseReservation(id: string, ctx: Ctx, outcome: string): void {
  const holding = ctx.reserved[id];
  ctx.stock[holding.item] = stockOf(ctx, holding.item) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = outcome;
  tryFillBacklog(ctx);
}

function reserveOrder(ctx: Ctx, id: string, item: string, qty: number): void {
  ctx.stock[item] = stockOf(ctx, item) - qty;
  ctx.reserved[id] = { item, qty };
  ctx.orders[id] = "reserved";
}

function backorderOrder(ctx: Ctx, id: string, item: string, qty: number): void {
  ctx.queue.push(id);
  ctx.pendingWants[id] = { item, qty };
  ctx.orders[id] = "backordered";
}

function handleOrder(event: Record<string, unknown>, ctx: Ctx): string | null {
  const id = event.id as string;
  if (ctx.orders[id] !== undefined) {
    return "duplicate order";
  }
  const qty = event.qty as number;
  if (stockOf(ctx, event.item as string) >= qty) {
    reserveOrder(ctx, id, event.item as string, qty);
  } else {
    backorderOrder(ctx, id, event.item as string, qty);
  }
  return null;
}

function handleCancel(event: Record<string, unknown>, ctx: Ctx): string | null {
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    releaseReservation(id, ctx, "cancelled");
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleShip(event: Record<string, unknown>, ctx: Ctx): string | null {
  const id = event.id as string;
  const reservation = ctx.reserved[id];
  if (reservation === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (event.qty === undefined || event.qty === reservation.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if ((event.qty as number) < reservation.qty) {
    reservation.qty = reservation.qty - (event.qty as number);
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleRestock(event: Record<string, unknown>, ctx: Ctx): string | null {
  ctx.stock[event.item as string] =
    stockOf(ctx, event.item as string) + (event.qty as number);
  tryFillBacklog(ctx);
  return null;
}

function handleExpire(event: Record<string, unknown>, ctx: Ctx): string | null {
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    releaseReservation(id, ctx, "expired");
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

type Validation = { name: string; check: (event: Record<string, unknown>) => boolean };

const validators: Record<string, Validation> = {
  id: {
    name: "id",
    check: (event) => typeof event.id !== "string" || (event.id as string).length === 0,
  },
  item: {
    name: "item",
    check: (event) => typeof event.item !== "string" || (event.item as string).length === 0,
  },
  qty: {
    name: "qty",
    check: (event) => !Number.isInteger(event.qty) || (event.qty as number) < 1,
  },
  optQty: {
    name: "qty",
    check: (event) =>
      event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1),
  },
};

const EVENT_SPEC: Record<string, string[]> = {
  order: ["id", "item", "qty"],
  cancel: ["id"],
  ship: ["id", "optQty"],
  restock: ["item", "qty"],
  expire: ["id"],
};

function validateEvent(event: Record<string, unknown>, spec: string[]): string | null {
  for (const kind of spec) {
    if (validators[kind].check(event)) {
      return "bad " + validators[kind].name;
    }
  }
  return null;
}

function runEvents(
  events: Record<string, unknown>[],
  ctx: Ctx,
): { ok: true } | { ok: false; error: string } {
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const type = event.type as string;
    const handler = HANDLERS[type];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const reason = validateEvent(event, EVENT_SPEC[type]) ?? handler(event, ctx);
    if (reason !== null) {
      return { ok: false, error: "event " + index + ": " + reason };
    }
  }
  return { ok: true };
}

function parseStock(input: Record<string, unknown>): Record<string, number> | null {
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const qty = rawStock[item];
    if (!Number.isInteger(qty) || (qty as number) < 0) {
      return null;
    }
    stock[item] = qty as number;
  }
  return stock;
}

function buildResult(ctx: Ctx): FulfillmentResult {
  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock = parseStock(input);
  if (stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Ctx = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };
  const outcome = runEvents(input.events as Record<string, unknown>[], ctx);
  if (!outcome.ok) {
    return outcome;
  }
  return buildResult(ctx);
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

