export type RetryMode = "exponential" | "linear";

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: RetryMode;
}

const DEFAULT_RETRY_CONFIG: Readonly<RetryConfig> = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

function parseBoundedInt(
  rawValue: string | undefined,
  min: number,
  max: number,
): number | undefined {
  if (rawValue === undefined) {
    return undefined;
  }
  const value = Number(rawValue);
  if (!Number.isInteger(value) || value < min || value > max) {
    return undefined;
  }
  return value;
}

function parseBoolean(rawValue: string | undefined): boolean | undefined {
  if (rawValue === "true") {
    return true;
  }
  if (rawValue === "false") {
    return false;
  }
  return undefined;
}

function parseMode(rawValue: string | undefined): RetryMode | undefined {
  if (rawValue === "exponential" || rawValue === "linear") {
    return rawValue;
  }
  return undefined;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = parseBoundedInt(raw.maxAttempts, 1, 10);
  if (maxAttempts !== undefined) {
    config.maxAttempts = maxAttempts;
  }

  const backoffMs = parseBoundedInt(raw.backoffMs, 0, Number.MAX_SAFE_INTEGER);
  if (backoffMs !== undefined) {
    config.backoffMs = backoffMs;
  }

  const jitter = parseBoolean(raw.jitter);
  if (jitter !== undefined) {
    config.jitter = jitter;
  }

  const mode = parseMode(raw.mode);
  if (mode !== undefined) {
    config.mode = mode;
  }

  return config;
}

