export type RetryMode = "exponential" | "linear";

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: RetryMode;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const MAX_ATTEMPTS_MIN = 1;
const MAX_ATTEMPTS_MAX = 10;

const VALID_MODES: ReadonlySet<RetryMode> = new Set(["exponential", "linear"]);

type Parser = (raw: string) => RetryConfig[keyof RetryConfig] | undefined;

const PARSERS: Readonly<Record<keyof RetryConfig, Parser>> = {
  maxAttempts: (raw) => {
    const value = Number(raw);
    return Number.isInteger(value) && value >= MAX_ATTEMPTS_MIN && value <= MAX_ATTEMPTS_MAX
      ? value
      : undefined;
  },
  backoffMs: (raw) => {
    const value = Number(raw);
    return Number.isInteger(value) && value >= 0 ? value : undefined;
  },
  jitter: (raw) => {
    if (raw === "true") {
      return true;
    }
    if (raw === "false") {
      return false;
    }
    return undefined;
  },
  mode: (raw) => (VALID_MODES.has(raw as RetryMode) ? (raw as RetryMode) : undefined),
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: Record<keyof RetryConfig, unknown> = { ...DEFAULT_RETRY_CONFIG };

  for (const key of Object.keys(PARSERS) as (keyof RetryConfig)[]) {
    const rawValue = raw[key];
    if (rawValue === undefined) {
      continue;
    }
    const parsed = PARSERS[key](rawValue);
    if (parsed !== undefined) {
      config[key] = parsed;
    }
  }

  return config as RetryConfig;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const MAX_ATTEMPTS_MIN = 1;
const MAX_ATTEMPTS_MAX = 10;
const BACKOFF_MIN = 0;

const SUPPORTED_MODES = new Set(["exponential", "linear"]);

function parseBoundedInteger(
  raw?: string,
  min?: number,
  max?: number,
): number | null {
  if (raw === undefined) {
    return null;
  }
  const value = Number(raw);
  if (!Number.isInteger(value)) {
    return null;
  }
  if (min !== undefined && value < min) {
    return null;
  }
  if (max !== undefined && value > max) {
    return null;
  }
  return value;
}

function parseBoolean(raw: string | undefined, fallback: boolean): boolean {
  if (raw === "true") {
    return true;
  }
  if (raw === "false") {
    return false;
  }
  return fallback;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const maxAttempts =
    parseBoundedInteger(
      raw.maxAttempts,
      MAX_ATTEMPTS_MIN,
      MAX_ATTEMPTS_MAX,
    ) ?? DEFAULT_RETRY_CONFIG.maxAttempts;

  const backoffMs =
    parseBoundedInteger(raw.backoffMs, BACKOFF_MIN) ??
    DEFAULT_RETRY_CONFIG.backoffMs;

  const jitter = parseBoolean(raw.jitter, DEFAULT_RETRY_CONFIG.jitter);

  const mode =
    raw.mode !== undefined && SUPPORTED_MODES.has(raw.mode)
      ? raw.mode
      : DEFAULT_RETRY_CONFIG.mode;

  return { maxAttempts, backoffMs, jitter, mode };
}

