export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: Readonly<RetryConfig> = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const MODE_LOOKUP: Readonly<Record<string, string>> = {
  exponential: "exponential",
  linear: "linear",
};
const JITTER_LOOKUP: Readonly<Record<string, boolean>> = {
  true: true,
  false: false,
};
const MAX_ATTEMPTS_LIMIT = 10;

function pick<T>(raw: string | undefined, lookup: Record<string, T>, fallback: T): T {
  if (raw !== undefined && raw in lookup) {
    return lookup[raw];
  }
  return fallback;
}

function parseBounded(raw: string | undefined, upper: number, fallback: number): number {
  if (raw === undefined) {
    return fallback;
  }
  const value = Number(raw);
  if (Number.isInteger(value) && value >= 1 && value <= upper) {
    return value;
  }
  return fallback;
}

function parseUnbounded(raw: string | undefined, fallback: number): number {
  if (raw === undefined) {
    return fallback;
  }
  const value = Number(raw);
  if (Number.isInteger(value) && value >= 0) {
    return value;
  }
  return fallback;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  return {
    maxAttempts: parseBounded(raw.maxAttempts, MAX_ATTEMPTS_LIMIT, DEFAULT_RETRY_CONFIG.maxAttempts),
    backoffMs: parseUnbounded(raw.backoffMs, DEFAULT_RETRY_CONFIG.backoffMs),
    jitter: pick(raw.jitter, JITTER_LOOKUP, DEFAULT_RETRY_CONFIG.jitter),
    mode: pick(raw.mode, MODE_LOOKUP, DEFAULT_RETRY_CONFIG.mode),
  };
}

export interface RetryConfig {
