  const maxAttempts = parseBoundedInt(raw.maxAttempts, MIN_ATTEMPTS, MAX_ATTEMPTS);
  if (maxAttempts !== undefined) {
    config.maxAttempts = maxAttempts;
  }

  const backoffMs = parseBoundedInt(raw.backoffMs, 0, Number.MAX_VALUE);
  if (backoffMs !== undefined) {
    config.backoffMs = backoffMs;
  }

  const jitter = parseBoolean(raw.jitter);
  if (jitter !== undefined) {
    config.jitter = jitter;
  }

  if (raw.mode !== undefined && VALID_MODES.has(raw.mode)) {
    config.mode = raw.mode;
  }

