  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const MAX_ATTEMPTS_RANGE = { min: 1, max: 10 };
const VALID_MODES = new Set(["exponential", "linear"]);

type FieldParser<T> = (raw: string) => T | undefined;

function parseBoundedInt(
  raw: string,
  min: number,
  max: number,
): number | undefined {
  const value = Number(raw);
  if (!Number.isInteger(value) || value < min || value > max) {
    return undefined;
  }
  return value;
}

function parseNonNegativeInt(raw: string): number | undefined {
  const value = Number(raw);
  if (!Number.isInteger(value) || value < 0) {
    return undefined;
  }
  return value;
}

const parseBoolean: FieldParser<boolean> = (raw) => {
  if (raw === "true") return true;
  if (raw === "false") return false;
  return undefined;
};

const parseMode: FieldParser<string> = (raw) =>
  VALID_MODES.has(raw) ? raw : undefined;

const FIELD_PARSERS: Record<
  keyof RetryConfig,
  FieldParser<RetryConfig[keyof RetryConfig]>
> = {
  maxAttempts: (raw) =>
    parseBoundedInt(
      raw,
      MAX_ATTEMPTS_RANGE.min,
      MAX_ATTEMPTS_RANGE.max,
    ) as RetryConfig["maxAttempts"],
  backoffMs: (raw) =>
    parseNonNegativeInt(raw) as RetryConfig["backoffMs"],
  jitter: parseBoolean as FieldParser<RetryConfig["jitter"]>,
  mode: parseMode as FieldParser<RetryConfig["mode"]>,
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  for (const key of Object.keys(FIELD_PARSERS) as Array<keyof RetryConfig>) {
    const value = raw[key];
    if (value === undefined) continue;

    const parsed = FIELD_PARSERS[key](value);
    if (parsed !== undefined) {
      config[key] = parsed;
    }
  }

  return config;
}

