export function shippingCost(order: ShipmentOrder): number {
  const tiers = BASE_PRICING[order.zone];
  const tier = tiers.find(({ upToKg }) => order.weightKg <= upToKg) ?? tiers[tiers.length - 1];
  let total = tier.price;

  if (order.priority) {
    total *= PRIORITY_MULTIPLIER;
  }

  if (order.fragile && order.weightKg > FRAGILE_SURCHARGE_MIN_WEIGHT_KG) {
    total += FRAGILE_SURCHARGE;
  }

  return total;
}

