}

const SIGNAL_BANDS: Array<{ min: number; max: number; label: string; severity: number }> = [
  { min: 0, max: 50, label: "standby", severity: 0 },
  { min: 50, max: 200, label: "idle", severity: 1 },
  { min: 200, max: 600, label: "active", severity: 2 },
  { min: 600, max: 900, label: "loaded", severity: 3 },
  { min: 900, max: Number.POSITIVE_INFINITY, label: "critical", severity: 4 },
];

function signalClass(millivolts: number): SignalClass {
  for (const band of SIGNAL_BANDS) {
    if (millivolts >= band.min && millivolts < band.max) {
      return { label: band.label, severity: band.severity };
    }
  }
  return { label: "negative", severity: 5 };
}

